        const { label, tone } = verdictLook(claim);
        const mark = element("button", undefined, "vfc-mark");
        mark.type = "button";
        mark.dataset.tone = tone;
        mark.dataset.settled = String(
          claim.check.state === "done" || claim.check.state === "failed",
